<script>
import api from '../api.js';
export default {name:'CsvExport',props:{project:String,target:String,spec:Object,query:Object,selectedKeys:Array},emits:['close'],data(){return {columns:this.spec.fields.filter(f=>!f.hidden&&f.supported&&!['gantt','work-hours'].includes(f.renderer)&&f.kind!=='heading').map(f=>f.name),selection:this.selectedKeys?.length?'selected':'matched',valueMode:'display',delimiter:',',busy:false,error:'',success:false}},methods:{async save(){this.busy=true;this.error='';this.success=false;try{await api.downloadCsv({...this.query,project:this.project,target:this.target,config_revision:this.spec.revision,search_type:this.spec.type,columns:this.columns,selection:this.selection,keys:this.selectedKeys,value_mode:this.valueMode,delimiter:this.delimiter});this.success=true}catch(e){this.error=e.message}finally{this.busy=false}}}};
</script>
<template>
<div class="modal-backdrop" @click.self="!busy&&$emit('close')"><section class="modal csv-export" role="dialog" aria-modal="true" aria-labelledby="csv-title"><header><div><small>{{spec.type}} · {{spec.view}}</small><h2 id="csv-title">Экспорт CSV из представления</h2></div><button :disabled="busy" @click="$emit('close')" aria-label="Закрыть экспорт">×</button></header><div class="audit-scroll"><p class="notice">Используются текущие фильтры и конфигурация. До 10 000 записей / 32 МиБ. Опасные для электронных таблиц значения защищаются апострофом; формулы не создаются.</p><label>Выборка<select v-model="selection" aria-label="Выборка экспорта"><option value="matched">Все совпадения поиска</option><option value="selected" :disabled="!selectedKeys?.length">Выбранные записи ({{selectedKeys?.length||0}})</option></select></label><label>Значения<select v-model="valueMode" aria-label="Значения экспорта"><option value="display">Отображаемые значения виджетов</option><option value="raw">Исходные значения обычных полей</option></select></label><label>Разделитель<select v-model="delimiter"><option value=",">Запятая</option><option value=";">Точка с запятой</option><option value="&#9;">Табуляция</option></select></label><h3>Колонки в порядке выбора</h3><div class="export-columns"><label v-for="f in spec.fields.filter(f=>f.kind!=='heading')" :key="f.name"><input type="checkbox" :value="f.name" v-model="columns">{{f.label}} <code>{{f.name}}</code><small v-if="!f.supported"> — виджет не перенесён</small></label></div><p v-if="error" class="error">{{error}}</p><p v-if="success" class="success">CSV сформирован и передан браузеру.</p></div><footer><button :disabled="busy" @click="$emit('close')">Закрыть</button><button class="primary" :disabled="busy||!columns.length" @click="save">{{busy?'Подготовка…':'Скачать CSV'}}</button></footer></section></div>
</template>
